import{_ as e,o as d,c as o,ah as a}from"./chunks/framework.DjU4PSOm.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-10-28T00:00:00.000Z"},"headers":[{"level":3,"title":"오늘 한 것 (2026-10-27 ~ 10-28)","slug":"오늘-한-것-2026-10-27-10-28","link":"#오늘-한-것-2026-10-27-10-28","children":[]},{"level":3,"title":"1. 구조 — 왜 DB 함수로 만들었나","slug":"_1-구조-—-왜-db-함수로-만들었나","link":"#_1-구조-—-왜-db-함수로-만들었나","children":[]},{"level":3,"title":"2. 기획 수정 — 받은 징을 숨기면 매칭이 안 된다","slug":"_2-기획-수정-—-받은-징을-숨기면-매칭이-안-된다","link":"#_2-기획-수정-—-받은-징을-숨기면-매칭이-안-된다","children":[]},{"level":3,"title":"3. 징에 일기 첨부 — 그 일기만 보고 결정","slug":"_3-징에-일기-첨부-—-그-일기만-보고-결정","link":"#_3-징에-일기-첨부-—-그-일기만-보고-결정","children":[]},{"level":3,"title":"4. 화면","slug":"_4-화면","link":"#_4-화면","children":[]},{"level":3,"title":"5. 검증 결과 (웹 브라우저, 테스트 계정 4개)","slug":"_5-검증-결과-웹-브라우저-테스트-계정-4개","link":"#_5-검증-결과-웹-브라우저-테스트-계정-4개","children":[]},{"level":3,"title":"6. 테스트 중 잡은 버그 — \\"Invalid Date\\"","slug":"_6-테스트-중-잡은-버그-—-invalid-date","link":"#_6-테스트-중-잡은-버그-—-invalid-date","children":[]},{"level":3,"title":"7. 남은 과제","slug":"_7-남은-과제","link":"#_7-남은-과제","children":[]}],"relativePath":"computer/project/Zing/09. 징 매칭 구현 (2026-10-28).md","filePath":"computer/project/Zing/09. 징 매칭 구현 (2026-10-28).md"}'),l={name:"computer/project/Zing/09. 징 매칭 구현 (2026-10-28).md"};function r(i,t,c,n,s,u){return d(),o("div",null,[...t[0]||(t[0]=[a('<h3 id="오늘-한-것-2026-10-27-10-28" tabindex="-1">오늘 한 것 (2026-10-27 ~ 10-28) <a class="header-anchor" href="#오늘-한-것-2026-10-27-10-28" aria-label="Permalink to &quot;오늘 한 것 (2026-10-27 ~ 10-28)&quot;">​</a></h3><p>피드에서 일기를 보는 것까지만 있던 상태에서 <strong>징(매칭) 기능 전체를 붙였다.</strong> 이번부터 작업 방식을 바꿔서, 단계별로 설명 듣고 직접 치던 것을 AI가 기능 단위로 끝까지 구현 → 브라우저 검증 → 보고하는 식(바이브 코딩)으로 진행했다. SQL 실행만 직접 Supabase SQL Editor에서 함.</p><table tabindex="0"><thead><tr><th>순서</th><th>작업</th><th>상태</th></tr></thead><tbody><tr><td>1</td><td><code>zings</code> 테이블 + RLS + DB 함수 (<code>sql/2026-10-27_zings.sql</code>)</td><td>완료, 실행 완료</td></tr><tr><td>2</td><td>받은 징 수락/거절 (기획 수정 반영)</td><td>완료</td></tr><tr><td>3</td><td>하루 징 3회 제한</td><td>완료</td></tr><tr><td>4</td><td>징에 일기 첨부 (<code>sql/2026-10-27_zings_attach_diary.sql</code>)</td><td>완료, 실행 완료</td></tr><tr><td>5</td><td>매칭 탭 (<code>MatchesScreen</code>), 일기 선택 창 (<code>ZingSendModal</code>)</td><td>완료</td></tr><tr><td>6</td><td>테스트 계정 4개로 전체 흐름 검증</td><td>완료, push 완료</td></tr></tbody></table><hr><h3 id="_1-구조-—-왜-db-함수로-만들었나" tabindex="-1">1. 구조 — 왜 DB 함수로 만들었나 <a class="header-anchor" href="#_1-구조-—-왜-db-함수로-만들었나" aria-label="Permalink to &quot;1. 구조 — 왜 DB 함수로 만들었나&quot;">​</a></h3><p>징 규칙(중복 금지, 매칭 상한, 하루 3회, 일기 첨부)을 프론트에서 검사하면, 앱을 거치지 않고 Supabase API를 직접 호출해서 우회할 수 있다. 그래서:</p><ul><li><code>zings</code> 테이블에는 <strong>SELECT 정책만</strong> 둠 (내가 보냈거나 받은 row만).</li><li>INSERT/UPDATE 정책은 아예 없음 → 쓰기는 <code>security definer</code> 함수(<code>send_zing</code>, <code>decline_zing</code>)로만 가능.</li><li>프론트는 <code>supabase.rpc(&#39;send_zing&#39;, ...)</code>를 호출하고 결과만 믿음. 함수 안에서 <code>raise exception &#39;오늘 보낼 수 있는 징(3회)을 다 썼어요...&#39;</code>처럼 던지면 클라이언트에 <code>error.message</code>로 그대로 옴 → 화면에 바로 표시.</li></ul><p>CLAUDE.md의 &quot;권한 규칙은 가능한 RLS/Postgres 함수로 강제하고, 프론트는 그 결과를 신뢰한다&quot; 원칙을 처음 제대로 적용한 기능.</p><p><strong>동시성</strong>: A와 B가 거의 동시에 서로 징을 보내면, 둘 다 &quot;상대 징 없음&quot;으로 판단해 매칭이 안 될 수 있다. <code>pg_advisory_xact_lock</code>으로 두 사람 쌍 단위로 잠가서 순서대로 처리.</p><hr><h3 id="_2-기획-수정-—-받은-징을-숨기면-매칭이-안-된다" tabindex="-1">2. 기획 수정 — 받은 징을 숨기면 매칭이 안 된다 <a class="header-anchor" href="#_2-기획-수정-—-받은-징을-숨기면-매칭이-안-된다" aria-label="Permalink to &quot;2. 기획 수정 — 받은 징을 숨기면 매칭이 안 된다&quot;">​</a></h3><p>처음 구현은 &quot;누가 나에게 징을 보냈는지는 안 보임&quot;이었다. 그런데 이러면 <strong>둘이 우연히 서로를 골라야만</strong> 매칭되는데, 피드가 랜덤이면 그럴 확률이 거의 없다.</p><p>→ 받은 징은 받은 사람에게 보이게 바꾸고, 매칭 탭에서 수락/거절하도록 수정.</p><ul><li><strong>수락</strong> = 보낸 사람에게 징을 보내는 것과 같음 (<code>acceptZing</code>이 내부적으로 <code>sendZing</code> 호출). 하루 횟수에는 포함 안 됨 (<code>is_response = true</code>).</li><li><strong>거절</strong>은 보낸 사람에게 알리지 않음. 보낸 쪽엔 계속 &quot;징을 보냈어요&quot;로 보인다. 거절당했다는 상처를 주지 않기 위해.</li><li>거절했던 사람이 나중에 마음 바꿔 징을 보내면 바로 매칭.</li></ul><hr><h3 id="_3-징에-일기-첨부-—-그-일기만-보고-결정" tabindex="-1">3. 징에 일기 첨부 — 그 일기만 보고 결정 <a class="header-anchor" href="#_3-징에-일기-첨부-—-그-일기만-보고-결정" aria-label="Permalink to &quot;3. 징에 일기 첨부 — 그 일기만 보고 결정&quot;">​</a></h3><p>받은 징을 수락할지 판단할 근거가 필요했다. 피드는 절반 공개라 정보가 부족하고, 보낸 사람의 전체 일기를 다 보여주면 매칭 전 절반 공개 원칙이 깨진다.</p><p>→ <strong>징을 보낼 때 내 일기 하나를 골라서 같이 보내고, 받은 사람은 그 일기(전체 공개)만 보고 수락/거절.</strong></p><ul><li>일기가 하나도 없으면 징을 못 보냄 (&quot;먼저 일기를 써야 징을 보낼 수 있어요&quot;). 글을 안 쓰고 징만 뿌리는 걸 막는 효과도 있음.</li><li>첨부 일기를 나중에 지우면 <code>diary_id</code>가 null이 됨 (<code>on delete set null</code>) → &quot;함께 보낸 일기가 삭제됐어요&quot; 표시.</li><li>피드 카드에는 수락 버튼을 두지 않고 &quot;매칭 탭에서 확인하세요&quot;만 안내. 판단 근거를 첨부 일기 하나로 통일하기 위해.</li></ul><hr><h3 id="_4-화면" tabindex="-1">4. 화면 <a class="header-anchor" href="#_4-화면" aria-label="Permalink to &quot;4. 화면&quot;">​</a></h3><ul><li><strong>피드(홈)</strong>: 상단에 &quot;오늘 보낼 수 있는 징 n회&quot;. 카드 상태별 표시 — 징 보내기 / 징을 보냈어요 / OO님이 일기와 함께 징을 보냈어요 / 매칭된 상대예요(전체 공개).</li><li><strong>일기 선택 창(<code>ZingSendModal</code>)</strong>: 내 일기 목록, 최신 일기가 기본 선택.</li><li><strong>매칭 탭(<code>MatchesScreen</code>)</strong>: 동시 매칭 n/상한 · 남은 징 → 받은 징 카드(첨부 일기 + 수락/거절) → 매칭된 상대 목록(현재 단계 표시).</li><li>탭에 들어올 때마다 새로 불러오도록 <code>useFocusEffect</code> 사용 (다른 탭에서 매칭이 생겼을 수 있음).</li></ul><hr><h3 id="_5-검증-결과-웹-브라우저-테스트-계정-4개" tabindex="-1">5. 검증 결과 (웹 브라우저, 테스트 계정 4개) <a class="header-anchor" href="#_5-검증-결과-웹-브라우저-테스트-계정-4개" aria-label="Permalink to &quot;5. 검증 결과 (웹 브라우저, 테스트 계정 4개)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>시나리오</th><th>결과</th></tr></thead><tbody><tr><td>일기 없이 징 보내기</td><td>일기 선택 창이 비어 있고 보내기 버튼 비활성화</td></tr><tr><td>일기 골라서 징 보내기</td><td>성공, 남은 횟수 3 → 2</td></tr><tr><td>하루 4번째 징</td><td>&quot;오늘 보낼 수 있는 징(3회)을 다 썼어요&quot;로 차단</td></tr><tr><td>받은 징 화면</td><td>첨부 일기 전체 + 수락/거절</td></tr><tr><td>수락</td><td>매칭 1/3명, 수락한 쪽 남은 횟수 그대로</td></tr><tr><td>매칭 후 피드</td><td>상대 일기 전체 공개</td></tr><tr><td>보낸 쪽 매칭 탭</td><td>&quot;1단계 · 반응&quot;으로 표시</td></tr><tr><td>거절</td><td>받은 사람 목록에서만 사라지고 보낸 사람은 계속 &quot;보냈어요&quot;</td></tr></tbody></table><hr><h3 id="_6-테스트-중-잡은-버그-—-invalid-date" tabindex="-1">6. 테스트 중 잡은 버그 — &quot;Invalid Date&quot; <a class="header-anchor" href="#_6-테스트-중-잡은-버그-—-invalid-date" aria-label="Permalink to &quot;6. 테스트 중 잡은 버그 — &quot;Invalid Date&quot;&quot;">​</a></h3><p>일기 선택 창의 날짜가 전부 &quot;Invalid Date&quot;로 나왔다.</p><ul><li>원인: DB는 <code>created_at</code>(snake_case), 앱 타입은 <code>createdAt</code>(camelCase)인데, 기존 <code>getDiaries</code>가 <code>data as Diary[]</code>로 <strong>캐스팅만</strong> 하고 있었다. TS는 캐스팅을 믿으니 타입 체크는 통과하지만 실제 값은 <code>undefined</code> → <code>new Date(undefined)</code>.</li><li>지금까지 안 드러난 이유: 이 값을 화면에 쓰는 곳이 없었음.</li><li>수정: 변환 함수 <code>toDiary(row)</code>를 만들어 <code>createDiary</code>, <code>getDiaries</code>, <code>updateDiary</code>, 피드에 모두 적용.</li><li>교훈: <strong><code>as</code>는 변환이 아니라 &quot;믿어줘&quot;일 뿐.</strong> DB row는 반드시 매퍼를 거칠 것.</li></ul><hr><h3 id="_7-남은-과제" tabindex="-1">7. 남은 과제 <a class="header-anchor" href="#_7-남은-과제" aria-label="Permalink to &quot;7. 남은 과제&quot;">​</a></h3><ul><li><strong>절반 공개가 앱에서만 적용됨</strong>: <code>diaries</code> SELECT 정책이 전체 허용이라 API 직접 호출하면 전문을 볼 수 있음. DB 차원 보호 필요 (보안 과제).</li><li><strong>하루 기준 불일치</strong>: 징은 한국 시간 자정, 일기 하루 1개 제한은 기기 시간 자정. 하나로 통일 필요.</li><li>받은 징 카드에 닉네임·국적도 같이 보임 — &quot;일기만 보고 결정&quot; 취지라면 숨길지 검토.</li><li>다음 기능: 매칭된 상대 일기 상세, 단계별 소통(1단계 반응부터), 채팅, 번역(API 미정).</li><li>Android Expo Go 실기기 테스트 아직 안 함.</li><li>런칭 전: Supabase &quot;Confirm email&quot; 다시 켜기, <code>.ac.kr</code> 체크 추가.</li></ul>',32)])])}const g=e(l,[["render",r]]);export{_ as __pageData,g as default};
